/* ===== V33.30 · Descargar «Perfil de usuario (PDF)» desde el menu de Ayuda =====
   Agrega en la cabecera del modal de Ayuda (#hlp) un boton que descarga la ficha
   «Perfil de usuario y requisitos del sistema» en PDF (tema Entalpia). El PDF va
   incrustado (base64) para que funcione sin conexion. Solo agrega UI; no toca el calculo. */
(function(){
 const PDF_B64="";
 const toast=m=>{try{(window.bgToast||console.log)(m);}catch(e){}};
 function dl(){
  try{
   const bin=atob(PDF_B64),n=bin.length,by=new Uint8Array(n);
   for(let i=0;i<n;i++)by[i]=bin.charCodeAt(i);
   const blob=new Blob([by],{type:'application/pdf'}),url=URL.createObjectURL(blob);
   const a=document.createElement('a');a.href=url;a.download='Perfil_Usuario_Isoflux.pdf';
   document.body.appendChild(a);a.click();a.remove();
   setTimeout(()=>URL.revokeObjectURL(url),5000);
   toast('\u2b07\ufe0f Descargando «Perfil de usuario (PDF)»');
  }catch(e){toast('No se pudo descargar el PDF: '+e.message);}
 }
 function add(){
  const hdr=document.querySelector('#hlp header');
  if(!hdr||document.getElementById('bperfilpdf'))return !!hdr;
  const x=document.getElementById('hx');
  const b=document.createElement('button');b.id='bperfilpdf';
  b.textContent='\ud83d\udcc4 Perfil de usuario (PDF)';
  b.title='Descargar la ficha «Perfil de usuario y requisitos del sistema» en PDF (tema Entalpia)';
  b.style.marginRight='8px';
  b.onclick=dl;
  if(x&&x.parentNode===hdr)hdr.insertBefore(b,x);else hdr.appendChild(b);
  return true;
 }
 let k=0;const t=setInterval(()=>{if(add()||++k>60)clearInterval(t);},300);
 window.PERFILPDF={dl};
})();
